                {
                  "label": "Tool layer",
                  "detail": "Least-privilege, scoped, short-lived credentials per tool"
                },
                {
                  "label": "Execution",
                  "detail": "Sandboxed code with controlled, allow-listed egress"
                },
                {
                  "label": "Data layer",
                  "detail": "Authorization re-checked here, independent of the model"
                }
